create function private.c1_create_source_review_issue(target_company_id uuid,target_source_selection_id uuid,target_input jsonb,target_request_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_context jsonb; v_id uuid:=gen_random_uuid();
begin v_context:=private.c1_source_context(target_company_id,'cost.prepare'); if not exists(select 1 from public.source_selections selection where selection.id=target_source_selection_id and selection.tenant_id=(v_context->>'tenantId')::uuid and selection.company_id=target_company_id) then raise exception using errcode='P0001',message='RESOURCE_NOT_FOUND'; end if; insert into public.source_review_issues(id,tenant_id,company_id,source_selection_id,related_selection_id,issue_kind,description,impact,opened_by) values(v_id,(v_context->>'tenantId')::uuid,target_company_id,target_source_selection_id,nullif(target_input->>'relatedSelectionId','')::uuid,target_input->>'issueKind',target_input->>'description',target_input->>'impact',(v_context->>'actorId')::uuid); return jsonb_build_object('id',v_id,'status','open','financialActivation',false); end; $$;
create function private.c1_resolve_source_review_issue(target_company_id uuid,target_id uuid,target_input jsonb,target_request_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_context jsonb; v_issue public.source_review_issues%rowtype;
begin v_context:=private.c1_source_context(target_company_id,'cost.prepare'); select * into v_issue from public.source_review_issues issue where issue.id=target_id and issue.tenant_id=(v_context->>'tenantId')::uuid and issue.company_id=target_company_id for update; if v_issue.id is null then raise exception using errcode='P0001',message='RESOURCE_NOT_FOUND'; end if; if v_issue.status='resolved' then raise exception using errcode='P0001',message='HISTORY_IMMUTABLE'; end if; if v_issue.version<>(target_input->>'expectedVersion')::bigint then raise exception using errcode='P0001',message='VERSION_CONFLICT'; end if; update public.source_review_issues set status='resolved',resolution=target_input->>'resolution',resolution_note=target_input->>'resolutionNote',resolution_reference=nullif(target_input->>'resolutionReference',''),resolved_by=(v_context->>'actorId')::uuid,resolved_at=now(),version=version+1 where id=target_id returning * into v_issue; return jsonb_build_object('id',v_issue.id,'status',v_issue.status,'financialActivation',false); end; $$;
create function public.c1_create_source_review_issue(target_company_id uuid,target_source_selection_id uuid,target_input jsonb,target_request_id uuid) returns jsonb language sql security definer set search_path='' as $$ select private.c1_create_source_review_issue(target_company_id,target_source_selection_id,target_input,target_request_id); $$;
create function public.c1_resolve_source_review_issue(target_company_id uuid,target_id uuid,target_input jsonb,target_request_id uuid) returns jsonb language sql security definer set search_path='' as $$ select private.c1_resolve_source_review_issue(target_company_id,target_id,target_input,target_request_id); $$;
revoke all on function public.c1_create_source_review_issue(uuid,uuid,jsonb,uuid), public.c1_resolve_source_review_issue(uuid,uuid,jsonb,uuid) from public, anon, authenticated;
